def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = str(value).strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = str(value)
        marker = re.search(r"ext\.?|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = str(value).strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = str(value).strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = str(value)
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        first_name = normalize_name(row["first_name"])
        last_name = normalize_name(row["last_name"])
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        opted_out = str(row["opted_out"]).strip().lower() in {
            "y", "yes", "true", "1"
        }
        tags = [
            tag.strip().lower()
            for tag in re.split(r"[;,]", str(row["tags"]))
            if tag.strip()
        ]

        prepared.append({
            "index": index,
            "first_name": first_name,
            "last_name": last_name,
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": str(row["source"]).strip().lower(),
            "updated": updated,
            "opted_out": opted_out,
            "tags": tags,
        })

    # Union-find makes identity matching transitive.
    parent = list(range(len(prepared)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    seen_email = {}
    seen_phone_name = {}
    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in seen_email:
                union(i, seen_email[row["email"]])
            else:
                seen_email[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in seen_phone_name:
                union(i, seen_phone_name[key])
            else:
                seen_phone_name[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated"].timestamp(),
                row["index"],
            ),
        )
        return chosen[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        latest = max(row["updated"] for row in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted({tag for row in group for tag in row["tags"]})),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
